select monday_id, monday_post_id, parent_post_id, auteur, le, contenu, tronque
from jsonb_to_recordset($monday$[{"monday_id": 10027165603, "auteur": "Nicolas VEDRINES", "le": "2025-09-11T09:11:01.000Z", "contenu": "EDL + Photo du lit\n\nBonjour Madame Mussio,\n\nSuite à notre conversation téléphonique, vous trouverez ci-joint la copie de l'état des lieux (EDL) sur lequel figurent les relevés de compteur, ainsi qu'une photo du sommier. Vous trouverez également en pièce jointe la photo du sommier cassé que votre locataire nous a adressée.\n\nDans l'attente de votre retour,\n\nBien à vous,\nNicolas VEDRINES", "tronque": false, "monday_post_id": 4480798393, "parent_post_id": null}, {"monday_id": 10027165603, "auteur": "Nicolas VEDRINES", "le": "2025-09-15T10:00:51.000Z", "contenu": "EDL + Photo du lit\n\nBonjour,\n\nJe suis en lien avec le SAV pour le lit. J'étais obligé de fixer une date de retour du lit défectueux le 03/10 entre 8h20h. La veille les horaires seront affinés et une date de livraison pour le nouveau lit (nouveau model) 19/09 entre 15h et 20h. J'ai pris au plus tôt.\nSi les dates ne lui conviennent pas il peut me donner ses dates mais le SAV ne va pas le contacter directement.\nLa garantie du lit fonctionne uniquement si il a bien gardé le lit défectueux.\n\nJe reste à votre disposition si besoin.\nBien cordialement\n\nHelene Kervarec", "tronque": false, "monday_post_id": 4489663163, "parent_post_id": null}, {"monday_id": 10027165603, "auteur": "Nicolas VEDRINES", "le": "2025-09-16T08:03:27.000Z", "contenu": "SAV pour le lit\n\nBonjour Monsieur Pissy,\n\nNous vous transférons ci-dessous le courriel que votre propriétaire vient de nous adresser concernant le remplacement de votre sommier.\n\nBonjour,\n\nJe suis en contact avec le SAV concernant le lit. J'ai dû fixer une date de retour pour le lit défectueux le 3 octobre, entre 8h et 20h. La veille, les horaires seront affinés, et une date de livraison sera programmée pour le nouveau lit (un nouveau modèle) le 19 septembre, entre 15h et 20h. J'ai choisi les créneaux les plus proches disponibles.\n\nSi ces dates ne vous conviennent pas, vous pouvez me communiquer vos disponibilités, mais le SAV ne vous contactera pas directement. La garantie du lit ne fonctionnera que si le lit défectueux a bien été conservé.\n\nJe reste à votre disposition si besoin.\nBien cordialement\n\nMerci de nous tenir informés si ces dates ne vous conviennent pas.\n\nBonne journée,\nVotre Gestionnaire\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30", "tronque": false, "monday_post_id": 4493367058, "parent_post_id": null}, {"monday_id": 10027165603, "auteur": "Nicolas VEDRINES", "le": "2025-09-16T08:07:49.000Z", "contenu": "EDL + Photo du lit\n\nBonjour Madame Kervarec,\n\nJe vous remercie pour ces informations. Je vais les transmettre à votre locataire et vous tiendrai informée de la suite.\n\nCordialement,\nVotre Gestionnaire", "tronque": false, "monday_post_id": 4493374857, "parent_post_id": null}, {"monday_id": 10027165603, "auteur": "Marion Brenot", "le": "2025-11-10T10:14:58.000Z", "contenu": "le 10/11 laissé sms au locataire pour qu'il me confirme que le sommier avait été remplacé\n\nil me répond que c'est ok\n\nj'informe le bailleur\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWsCZDPvlXFzngchBjcJqcpHpQCjQXJTjxmRSXnvBhvScFkwBjbRJvdZxp...\n\n", "tronque": false, "monday_post_id": 4655359794, "parent_post_id": null}, {"monday_id": 10029090500, "auteur": "Nicolas VEDRINES", "le": "2025-09-11T13:20:51.000Z", "contenu": "État des lieux – éléments détériorés - appartement Fleury Mérogis\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\n---------- Forwarded message ---------\nDe : UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com>\nDate: ven. 5 sept. 2025 à 17:02\nSubject: Re: État des lieux – éléments détériorés - appartement Fleury Mérogis\nTo: Elise Levasseur <elise.levasseur28@gmail.com>\n\nBonjour Madame Levasseur,\n\nJe vous en prie.\n\nPour toute demande concernant l'installation de portes sur l'armoire, je préfère que vous passiez par nous. Cela nous permettra d'assurer un suivi précis de votre dossier et d'éviter toute discussion inutile.\n\nBien cordialement,\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\nLe ven. 5 sept. 2025 à 16:53, Elise Levasseur <elise.levasseur28@gmail.com> a écrit :\n\nBonjour,\n\nMerci pour votre retour et vos réponses !\n\nPour l’installation de portes sur l’armoire, puis-je contacter directement la propriétaire par mail, pour avoir son accord écrit ? Ou je vois directement avec l’agence ?\n\nBien cordialement,\nElise Levasseur\n\nLe ven. 5 sept. 2025 à 15:13, UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com> a écrit :\n\nBonjour Mme Levasseur,\n\nNous faisons suite à votre courriel concernant les équipements présents dans votre logement situé 102 Rue Anaïs Nin à Fleury-Mérogis et nous vous remercions de nous avoir contactés.\n\nNous confirmons que bien que votre contrat soit un bail d'habitation non meublé, les appareils électroménagers ainsi que la penderie de la chambre sont bien listés dans l'état des lieux d'entrée. De ce fait, ils sont considérés comme mis à votre disposition par la propriétaire et entrent dans le cadre des obli", "tronque": true, "monday_post_id": 4481342008, "parent_post_id": null}, {"monday_id": 10029090500, "auteur": "Marion Brenot", "le": "2025-09-30T14:02:49.000Z", "contenu": "traité en directe avec les bailleurs tout est ok", "tronque": false, "monday_post_id": 4533208234, "parent_post_id": null}, {"monday_id": 10029159900, "auteur": "Nicolas VEDRINES", "le": "2025-09-16T08:20:18.000Z", "contenu": "Devis BIOGAZ CONFORT n°2757\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\n---------- Forwarded message ---------\nDe : said haddad <said.haddad16@outlook.fr>\nDate: jeu. 11 sept. 2025 à 21:43\nSubject: Re: Devis BIOGAZ CONFORT n°2757\nTo: votregestionnaire@udi-immo.com <votregestionnaire@udi-immo.com>, udi-immo_pulse_9086656180_6c6ae45fe2b128b4009e__14187156@use1.mx.monday.com <udi-immo_pulse_9086656180_6c6ae45fe2b128b4009e__14187156@use1.mx.monday.com>\n\nBonjour,\n\nJe vous envoie les factures en pièce jointe.\n\nCordialement,\n\nSaid HADDAD\n\nEnvoyé à partir deOutlook pour Android\n\nFrom: UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com>\nSent: Thursday, September 11, 2025 3:40:50 PM\nTo: said haddad <said.haddad16@outlook.fr>; udi-immo_pulse_9086656180_6c6ae45fe2b128b4009e__14187156@use1.mx.monday.com <udi-immo_pulse_9086656180_6c6ae45fe2b128b4009e__14187156@use1.mx.monday.com>\nSubject: Fwd: Devis BIOGAZ CONFORT n°2757\n\nBonjour MonsieurHaddad,\n\nComme suite à notre récent échange téléphonique concernant le problème de chaudière rencontré par vos locataires, je tenais à vous informer de l'intervention de notre chauffagiste.\n\nIl a réussi à redémarrer la chaudière. Cependant, suite à ses constatations, un devis a été établi pour un désembouage de l'installation de chauffage. Ces travaux vous incombent, car vos locataires viennent tout juste d'emménager.\n\nMerci de bien vouloir me confirmer votre accord. Sans votre validation, en cas de récidive du problème ou de panne du système de chauffage liée à ce désembouage, vous seriez tenu responsable des frais engendrés.\n\nCordialement,\nVotre Gestionnaire\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30", "tronque": false, "monday_post_id": 4493405212, "parent_post_id": null}, {"monday_id": 10029159900, "auteur": "Nicolas VEDRINES", "le": "2025-09-16T08:23:00.000Z", "contenu": "Suite à intervention de l'entreprise BioGaz Confort pour le redémarrage de la chaudière en défaut ces dernier on fait un devis de désembouage or M & Mme Haddad on fait un désembouage le 04/04/2025", "tronque": false, "monday_post_id": 4493409310, "parent_post_id": null}, {"monday_id": 10059594080, "auteur": "Nicolas VEDRINES", "le": "2025-09-16T09:28:19.000Z", "contenu": "Demande d'intervention\n\nDe : UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com>\nDate: mar. 16 sept. 2025 à 11:27\nSubject: Demande d'intervention\nTo: Marianne RIVIERE <mmarianne.riviere@gmail.com>\n\nMadame Rivière,\n\nJe fais suite à notre conversation téléphonique de ce jour concernant la demande d'intervention pour le ménage de la maison située 1 impasse des Oiseaux, 91590 Mondeville.\n\nL'intervention est prévue pour le jeudi 18 septembre à 14h. Vous trouverez ci-joint le mesurage de la maison.\n\nLes clés (n°52) sont à votre disposition à l'agence de Corbeil-Essonnes, 2 rue Charles Drezet. Nous vous serions reconnaissants de bien vouloir les redéposer le soir même ou au plus tard le lendemain matin, car l'état des lieux est programmé le vendredi à 14h.\n\nJe vous remercie de votre collaboration.\n\nCordialement,\nVotre Gestionnaire\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30", "tronque": false, "monday_post_id": 4493540324, "parent_post_id": null}, {"monday_id": 10059594080, "auteur": "Marion Brenot", "le": "2025-09-23T08:15:35.000Z", "contenu": "Attent facture déduction DG", "tronque": false, "monday_post_id": 4513105258, "parent_post_id": null}, {"monday_id": 10059785467, "auteur": "Nicolas VEDRINES", "le": "2025-09-22T08:59:46.000Z", "contenu": "Réfection des joints de carrelage au sol de la saale de bains\n\nBonjour Ludovic,\n\nJe fais suite à notre conversation concernant les travaux de réfection des joints de carrelage gris au sol dans la salle de bains de l'appartement situé au 23 Rue Maurice Berteaux, 91100 Corbeil-Essonnes. Les propriétaires bailleurs sont Martine et Bernard PETIT, et les locataires sont Marie MENDES et Mohammed CISSE .\n\nLa locataire a contacté Marie MENDES et Mohammed CISSE au 0659627458 pour planifier cette intervention.\n\nJe te remercie de nous tenir informé de la date prévue pour ces travaux.\n\nBien à toi", "tronque": false, "monday_post_id": 4509201917, "parent_post_id": null}, {"monday_id": 10059785467, "auteur": "Marion Brenot", "le": "2025-09-30T14:06:49.000Z", "contenu": "relance ludo pour date intervention\n\nhttps://mail.google.com/mail/u/0/#sent/CllgCJqVwLpxcbJwtgLkshtjKVrJBTJRXBtRqqnNXqxjldltMzbvdCVSxNrJx...", "tronque": false, "monday_post_id": 4533228581, "parent_post_id": null}, {"monday_id": 10062444092, "auteur": "Nicolas VEDRINES", "le": "2025-09-16T14:51:17.000Z", "contenu": "https://udi-immo.monday.com/boards/8959412206/pulses/8959412248", "tronque": false, "monday_post_id": 4494460393, "parent_post_id": null}, {"monday_id": 10645418497, "auteur": "Marion Brenot", "le": "2025-11-26T14:04:01.000Z", "contenu": "Le propriétaire c'est rendu compte qu'une des vitres était cassée.\n\nLe locataire m'informe qu'il a fait une déclaration à son assurance et attend leur retour pour faire les réparation, il va d'ici là protéger au mieux la fenêtre pour limiter l'entrée d'ai froid.\n\nIl m'informe également qu'il avait vu avec un des propriétaires pour faire des travaux afin de limiter les remontées d'odeur d'eaux usées. cela rends l'utilisation du local autre que pour du stockage impossible tellement les odeurs sont fortes.\n\n\n\nJe résumé cela à Nixo pour transmission aux bailleurs.\n\nhttps://mail.google.com/mail/u/0/#sent/CllgCJftvBfgDsWbWgZkfXLVTHnvxsqqWFqDvCmHxDpHvtXpPTvnSHtRHdpFd...\n\n", "tronque": false, "monday_post_id": 4703824949, "parent_post_id": null}, {"monday_id": 10645418497, "auteur": "Marion Brenot", "le": "2025-12-10T14:45:40.000Z", "contenu": "je relance Nico pour les travaux sur les remontées d'odeurs\n\nhttps://mail.google.com/mail/u/0/#sent/CllgCJftvBfgDsWbWgZkfXLVTHnvxsqqWFqDvCmHxDpHvtZpSXpPKtKFBGkwN...", "tronque": false, "monday_post_id": 4741215945, "parent_post_id": null}, {"monday_id": 10645418497, "auteur": "Marion Brenot", "le": "2026-01-21T13:04:08.000Z", "contenu": "relance locataire\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWrRnZfTdWHZbxQMkjPDqvrHHCtftlMskRBwsZvLCsHfNDhgZGJlprKbWR...", "tronque": false, "monday_post_id": 4851480507, "parent_post_id": null}, {"monday_id": 10645418497, "auteur": "Marion Brenot", "le": "2026-02-11T10:45:31.000Z", "contenu": "pas de retour du locataire je cloture", "tronque": false, "monday_post_id": 4915203074, "parent_post_id": null}, {"monday_id": 10655291636, "auteur": "Marion Brenot", "le": "2025-11-27T19:52:53.000Z", "contenu": "Mme BROQUET m'informe d'une panne de chaudière, Mr ALIBERTI c'est rendu sur place des pièces sont à changer j'attends le devis\n\n", "tronque": false, "monday_post_id": 4707699990, "parent_post_id": null}, {"monday_id": 10655291636, "auteur": "Nicolas VEDRINES", "le": "2025-11-27T19:53:28.000Z", "contenu": "Ordre de mission UDI Gestion - Sinistre au 3 Rue Féray, 91100 Corbeil-Essonnes\n\nOrdre de Mission - UDI Gestion\n\n****************\nOrdre de Mission\n****************\n\nBonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n-------------------------\nDétails de l'intervention\n-------------------------\n\nNature du sinistre : Panne de chaudière\n\nNature du bien : Appartement\n\nAdresse du bien : 3 Rue Féray, 91100 Corbeil-Essonnes\n\nMoyen d'accès : Contacter locataire\n\nRéférence à rappeler\n--------------------\n\nMerci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nSCI FIND / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 3 Rue Féray, 91100 Corbeil-Essonnes\n\nContact Locataire\n-----------------\n\nNom : BROQUET ATLAN Emma - L55\n\nAdresse : 3 Rue Féray, 91100 Corbeil-Essonnes\n\nTéléphone : 0619300818\n\nNous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\nUDI Gestion\nSAS au capital de 1000 € - RCS: EVRY n° 907 631 170\nSiège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\nN° TVA Intra-communautaire: FR23907631170\nCarte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\nNuméro Orias n° 23006870\n\nAssurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\nGarantie financière: QBE Insurance (400 000 €)\nMédiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr", "tronque": false, "monday_post_id": 4707700611, "parent_post_id": null}, {"monday_id": 10655291636, "auteur": "Marion Brenot", "le": "2025-11-28T07:25:55.000Z", "contenu": "reception devis\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvMMtrQVKBSZwDBbmzXTNRxQxNdJdWHcjVJWtpHBPjCxTFNskGfBGk...\n\nDevis.pdf\n\ntransmission au bailler pour accord\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWrRttWbtPMnWsRWfcgmXCTXmDGpWsFKkfVjgjWrhgXrWlHJrWFjbzvqGD...\n\n\n\n", "tronque": false, "monday_post_id": 4708341648, "parent_post_id": null}, {"monday_id": 10655291636, "auteur": "Marion Brenot", "le": "2025-12-01T11:48:02.000Z", "contenu": "validation devis par sms en attente travaux et facture\n\n", "tronque": false, "monday_post_id": 4712454008, "parent_post_id": null}, {"monday_id": 10655291636, "auteur": "Marion Brenot", "le": "2025-12-08T12:21:18.000Z", "contenu": "reception facture facture.pdf\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvMNTNjxnDQtLrglFKhzNVcBlPNTBHxWgzhWkDLtfCzfKsZtvSnVxW...\n\ntransmission audrey\n\n", "tronque": false, "monday_post_id": 4733067635, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2025-12-01T10:54:22.000Z", "contenu": "d'après le diag gaz il manque un robinet d'arrêt à la table de cuisson\n\nje fais une OM à Mr VIERA, plombier recommandé par ORPI", "tronque": false, "monday_post_id": 4712337628, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Nicolas VEDRINES", "le": "2025-12-01T10:55:27.000Z", "contenu": "Ordre de mission UDI Gestion - Sinistre au 9 Square Winston Churchill, 03100 Montluçon\n\nOrdre de Mission - UDI Gestion\n\n****************\nOrdre de Mission\n****************\n\nBonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n-------------------------\nDétails de l'intervention\n-------------------------\n\nNature du sinistre : robinet arrêt table de cuisson manquant\n\nNature du bien : Appartement\n\nAdresse du bien : 9 Square Winston Churchill, 03100 Montluçon\n\nMoyen d'accès : Clés agence\n\nRéférence à rappeler\n--------------------\n\nMerci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nTURPAULT Léo-Paul et TURPAULT Camille / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 9 Square Winston Churchill, 03100 Montluçon\n\nContact Locataire\n-----------------\n\nNom : DOGHMANE Inès\n\nAdresse : 9 Square Winston Churchill, 03100 Montluçon\n\nTéléphone : 33651286422\n\nNous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\nUDI Gestion\nSAS au capital de 1000 € - RCS: EVRY n° 907 631 170\nSiège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\nN° TVA Intra-communautaire: FR23907631170\nCarte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\nNuméro Orias n° 23006870\n\nAssurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\nGarantie financière: QBE Insurance (400 000 €)\nMédiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr", "tronque": false, "monday_post_id": 4712340254, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2025-12-11T10:33:40.000Z", "contenu": "reception devis\n\nD464 TURPAULT.pdf", "tronque": false, "monday_post_id": 4744417369, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2025-12-11T10:44:01.000Z", "contenu": "transmission au bailleur en attente retour\n\nhttps://mail.google.com/mail/u/0/#sent/CllgCJZdkbpKppsTvZJFrVtzxwPQjsLjMQgwcSdLTsDFHkhCnZQmcpKTdftPK...\n\n\n\n", "tronque": false, "monday_post_id": 4744434133, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2025-12-11T10:58:01.000Z", "contenu": "accord\n\nhttps://mail.google.com/mail/u/0/#inbox/jrjtXJTmZzkVpqqXgzNMwMDZfQcqzghMtdMjXqWCKrTxPhkqLNBzXdsMJSJr...\n\nje mandate mr viera\n\nhttps://mail.google.com/mail/u/0/#sent/GTvVlcSHxGqmCllJkljdnGpzBKWdvnbpPThvqQnKfLbWZCrkMFsPHpBSjCKpq...", "tronque": false, "monday_post_id": 4744453537, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2026-01-05T10:52:13.000Z", "contenu": "ROBINET A CHANGER Mr VIERA va prendre contact avec la locataire", "tronque": false, "monday_post_id": 4797293429, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2026-01-19T12:58:15.000Z", "contenu": "jerelance l'artisan pour savoir si les travaux sont faits\n\nhttps://mail.google.com/mail/u/0/#sent/GTvVlcSHxGqmCllJkljdnGpzBKWdvnbpPThvqQnKfLbWZCrkMFsPRBBshlMlX...", "tronque": false, "monday_post_id": 4843984382, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2026-01-20T05:32:26.000Z", "contenu": "travaux ok en attente de facture\n\nhttps://mail.google.com/mail/u/0/#inbox/CllgCHrjFBhPRprbGfDtHbgzgWvMfGVslqzbBGzPlWlCsXNtmHhgpLNtWgcc...", "tronque": false, "monday_post_id": 4846678187, "parent_post_id": null}, {"monday_id": 10668580171, "auteur": "Marion Brenot", "le": "2026-01-27T06:37:38.000Z", "contenu": "facture\n\nhttps://mail.google.com/mail/u/0/#inbox/CllgCHrjFBhPRprbGfDtHbgzgWvMfGVslqzbBGzPlWlCsXNtmHhknjphQPfX...\n\nF641 TURPAULT.pdf\n\ntransmise à audrey", "tronque": false, "monday_post_id": 4867252891, "parent_post_id": null}, {"monday_id": 10680585315, "auteur": "Marion Brenot", "le": "2025-12-02T12:04:29.000Z", "contenu": "le locataire m'informe qu'il n'y a pas d'attache exterieure pour les volets\n\nhttps://mail.google.com/mail/u/0/#inbox/CllgCHrkVVTNgMHStrwJXKRHCSXNctgHCZVqZdHWRCdwQRBCmQWHZsNCNSLT...", "tronque": false, "monday_post_id": 4716758593, "parent_post_id": null}, {"monday_id": 10680585315, "auteur": "Nicolas VEDRINES", "le": "2025-12-02T12:04:51.000Z", "contenu": "Information Sinistre - Votre bien situé au 62 rue du martroy\n\nInformation Sinistre - UDI Gestion\n\n********************\nInformation Sinistre\n********************\n\nBonjour,\n\nNous vous contactons pour vous informer qu'un sinistre nous a été signalé dans le bien que nous gérons pour votre compte.\n\n------------------\nRésumé du sinistre\n------------------\n\nNature du bien : Appartement\n\nAdresse du bien : 62 rue du martroy\n\nNature du sinistre : Pas d'attache exterieure pour les volets\n\nLocataire en place : Arnaud MORIN\n\nContact locataire : 33681391225\n\n-------------------------\nGestion de l'intervention\n-------------------------\n\nAfin de procéder aux investigations nécessaires et d'établir un devis pour les réparations, nous vous remercions de nous indiquer la marche à suivre. Veuillez s'il vous plaît choisir l'une des deux options ci-dessous :\n\nJe mandate UDI Gestion Je gère le sinistre moi-même Votre choix nous permettra de lancer la procédure appropriée sans délai.\n\nEn l'absence de retour de votre part, nous nous réservons le droit de mandater une entreprise pour les mesures conservatoires urgentes si la situation l'exige.\n\nCordialement,\n\nL'équipe UDI Gestion\n\nUDI Gestion\nSAS au capital de 1000 € - RCS: EVRY n° 907 631 170\nSiège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\nN° TVA Intra-communautaire: FR23907631170\nCarte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\nNuméro Orias n° 23006870\n\nAssurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\nGarantie financière: QBE Insurance (400 000 €)\nMédiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr", "tronque": false, "monday_post_id": 4716759502, "parent_post_id": null}, {"monday_id": 10680585315, "auteur": "Marion Brenot", "le": "2025-12-02T12:10:07.000Z", "contenu": "le propriétaire va faire passer son entrepreneur", "tronque": false, "monday_post_id": 4716772440, "parent_post_id": null}, {"monday_id": 10680585315, "auteur": "Marion Brenot", "le": "2026-01-07T11:59:59.000Z", "contenu": "l'entrepreneur va passer sous 10 jours pour fixer les taquets manquants\n\nj'informe le locataire\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWrRtsNLVxngfrSPXRFmBDKHLtBxgDTDtzPVklsbfhZllZnKdtzMkJmLfG...\n\n", "tronque": false, "monday_post_id": 4807716916, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-04T11:11:29.000Z", "contenu": "Mr OLEKO a fait appel à GARANKA pour un contrat annuel pour le chauffe eau qui a deux ans et n'est plus sous garantie, ils sont intervenu le 03/12/2025 et on remarqué des pièces à changer, je ne comprends pas leur devis de 925.13\n\n\n\nmail de garanka pour leur intervention\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvMNlGtwVLJbZWGGsDpxFSRzHcqfBCQrjBFnrbZRPZTGxQJDBQcqnn...\n\nDEVIS SUR INTERVENTION DU 03_12_2025.PDFINTERVENTION DU 03_12_2025.PDF\n\nmail du locataire reçu par garanka\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvMNlGvFdTrHNMCGvGNfhkbHmGhhPKgMwzcHpmgDqhbbdkGHstRmLp...\n\nattestation tva reçu de garanka par le locataire.PDFdevis reçu par le locataire de garanka_ different de ce que garanka a envoyé.pdf", "tronque": false, "monday_post_id": 4724721843, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-04T11:21:19.000Z", "contenu": "j'écris à garanka copie Mr OLEKO\n\nhttps://mail.google.com/mail/u/0/#sent/GTvVlcSDbhCLBRvcwCglDvgnbqwfMMTwmqfWtBGFCThdrQjMhZzvnbBhmQFPP...", "tronque": false, "monday_post_id": 4724748278, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-05T09:55:50.000Z", "contenu": "La société garanka m'appel pour m'indiquer qu'a son arrivée le chauffe eau fuyait il y avait une bassine en dessous\n\nils vont m'envoyer un mail pour valider cela et le montant des réparations\n\nLe locataire même sous garantie aurait du faire des entretient annuels il va donc devoir payer les réparations\n\nJ'appel Bastien MBP pour avoir des précision\n\nvoici la facture\n\nFACTURE 2023-8888 DU 31_05 - REMPL CHAUFFE EAU_BAIN.pdf\n\n", "tronque": false, "monday_post_id": 4728084630, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-05T10:09:25.000Z", "contenu": "j'appel le snpi\n\nIl faut un lien de causalité qui dit que suite a un defaut d'entretien et a la fuite cela a abimé le chauffe eau\n\nil faut un rapport de causalité\n\nje demande à garanka de me rappeler pour m'envoyer le bon rapport\n\n0169906234", "tronque": false, "monday_post_id": 4728103695, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-08T14:42:25.000Z", "contenu": "mail de la société qui a entretenu et constaté la fuite\n\nhttps://mail.google.com/mail/u/0/#inbox/CllgCHrgmQPFnHWVDfnNxhdJvtSkKzPsGnsJSPvfkVmWFJMsZNZRjdgBrVtl...\n\nBonjour Madame Brenot,\n\nNous sommes passé pour effectuer la visite annuelle chez M Oleko Opeta le 03/12/2025.\n\nLors de ce passage, la visite d’entretien a bien été effectuée ;\n\nLe type d’appareil n’étant pas référencé sur notre nomenclature interne, le technicien l’a noté sur son rapport d’intervention en toute lettre.\n\nLe technicien à son arrivé a constaté qu’un récipient était placé sous le chauffe-bain pour récupérer l’eau provenant d’une fuite.\n\nIl a établi le devis des pièces qui sont à changer pour la remise en état de l’appareil : corps de chauffe et valve à eau fuyards et bloc gaz impacté par la fuite risquant de se couper à tout moment.\n\nEn ce qui concerne la garantie, nous ne pourrons prendre en charge les pièces n’ayant ni information sur la mise en service du chauffe-bain, ni sur les entretiens effectués et enfin sur la carte de garantie qui doit être enregistrée chez le constructeur.\n\nVous pouvez néanmoins vous tourner vers l’installateur qui pourra peut-être prendre cette prestation à sa charge.\n\nJe reste disponible pour toute autre information.\n\n", "tronque": false, "monday_post_id": 4733503839, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-08T14:50:48.000Z", "contenu": "j'écris au locataire\n\nhttps://mail.google.com/mail/u/0/#sent/WhctKLbvMNlGvFdTrHNMCGvGNfhkbHmGhhPKgMwxtpsxfPCTgwrbrZpTLvxZH...\n\n", "tronque": false, "monday_post_id": 4733538296, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-09T09:31:38.000Z", "contenu": "le locataire ne veux pas payer\n\nJe valide cela par mail au locataire\n\nhttps://mail.google.com/mail/u/0/#sent/lLtBPchWxrGzrmkrRBVSWprnqwrGBMJfWBWvJpvnMNzwtVsbbFvTPTsBGdZxr...\n\nj'informe le bailleur\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWtDqNzwhfSTRkjbfVmfbThfGfQxKksxxQpNgnBjtdcWXMHKPrmMDBzSwZ...\n\n", "tronque": false, "monday_post_id": 4736661685, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-09T15:21:34.000Z", "contenu": "Mr OLEKO me dit que GARANKA a indiquer que ce n'était pas à lui de payer\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvMNlGvFdTrHNMCGvGNfhkbHmGhhPKgMwzcHpmgDqjNHpdSvMvMQvB...\n\nJr NELSON OLEKO\n---------------\n\n12:24 (il y a 3 heures)\n\nÀ moi\n\nLes réparations sont à votre charge. C'est pas à moi de prendre en charge selon Garanka.", "tronque": false, "monday_post_id": 4737611991, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-09T15:22:00.000Z", "contenu": "je demande des explications a garanka\n\nhttps://mail.google.com/mail/u/0/#inbox/DmwnWrRpdthnBLkrlJBWcqtZFBfZbnsxfhSjJtDctsnzNqvVbkXHCswGXkhg...\n\nBonjour je me permets de vous recontacter suite à nos différents échanges téléphoniques et votre dernier mail.J’ai j’informé le locataire MR Oleko que suite au non entretien annuel de son chauffe eau remplacé et 2023 et à vos constatations de fuite la semaine dernière il était à sa charge de faire les réparations car ils n’avait pas tenu ses obligations de locataires ce qui amenait aujourd’hui à des réparations sur le chauffe eau importantes.Il m’indique que vous lui auriez dit que les travaux était à la charge du bailleur.Je m’interroge sur la véracité de cela et si c’est le cas pourriez vous m’expliquer pourquoi vous avez indiqué cela?\nDans l’attente de votre retour\nCordialement", "tronque": false, "monday_post_id": 4737614756, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-09T15:22:25.000Z", "contenu": "garanka me répond\n\nhttps://mail.google.com/mail/u/0/#inbox/CllgCHrgmQPFnHWVDfnNxhdJvtSkKzPsGnsJSPvfkVmWFJMsZNZVfLMDBQBz...\n\nBonjour Madame Brenot,\n\nDans le cadre habituel d’un contrat d’entretien, le contrat est généralement à la charge du locataire et les pièces à la charge du propriétaire ou bailleur.\n\nCependant il vous appartient de contester auprès des occupants si leurs obligations de locataires n’ont pas été respectées.\n\n", "tronque": false, "monday_post_id": 4737617767, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-09T15:22:34.000Z", "contenu": "faire un point sur ce dossier", "tronque": false, "monday_post_id": 4737618941, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-12T09:19:36.000Z", "contenu": "bastien mbp VA VOIR POUR PRENDRE en garantie une partie des pièces", "tronque": false, "monday_post_id": 4747667643, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2025-12-15T13:31:50.000Z", "contenu": "Bastien MBP va passer faire un devis pour mettre un ballon classique\n\nje lui envoie les coordonnée du locataire\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWrRrlqxRVZbgNTNHPFLxFWGRfChfkhfNgkkLljfnKjWjfLKBDhznGNPkC...", "tronque": false, "monday_post_id": 4752695149, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2026-01-08T11:24:01.000Z", "contenu": "devis MBP\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvPRXQfbPcdGSqghjtkNPRCDZnvRxRrgkwncZkRbgqXfqWGktgMPRG...\n\nSalut nico\n\npour le ballon , il faut aler chercher une alim au tableau + modif plomberie\nje te met les 2 situations ( fourniture en prix d'achat sur les 2 )\n\nPour le budget fourniture ( prix d'achat )\nBallon extra plat et son équipements + électricité et plomberie = 450 € ht\n\nMain d'oeuvre/déplacement = 350 € ht\n\nou avec un ballon classic 100L , enleve 80 € ht sur la fourniture\n\n-------------------------------------------------------------------------------------\n\nchauffe eau gaz\n\nfourniture 680.00 € ht\nmain d'oeuvre 200.00 € ht\n\n", "tronque": false, "monday_post_id": 4812175153, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2026-01-08T11:31:31.000Z", "contenu": "j'appelle le locataire qui me raccroche au nez me disant que ce n'est pas à lui de payer et que Nico le rappelle.\n\nje demande à Bastien MBP si au changement du ballon il a proposé à Mr OLEKO un contrat d'entretien j'attends sa réponse avant que Nico appel Mr OLEKO", "tronque": false, "monday_post_id": 4812195551, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2026-01-08T13:11:54.000Z", "contenu": "Bastien me dit qu'il n'a pas de trace écrite de relance car il n'avait pas le mail de Mr OLEKO\n\nJe rappelle le SNPI pour connaitre notre responsabilité en cas de non relance pour entretien: nous n'avons pas d'obligation de rappel\n\narticle 7 loi juillet 1989.\n\n", "tronque": false, "monday_post_id": 4812467829, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2026-01-08T13:14:16.000Z", "contenu": "NICO VA RAPPELER SES OBLIGATION AU LOCATAIRE", "tronque": false, "monday_post_id": 4812473661, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2026-01-12T08:35:41.000Z", "contenu": "on attends un nouveau diagnostic de bastien\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvQSfsnrJMRTVrRxtpQnGWwpnvBZqbtHpwXrFdBMTPxWDQPdWfgBkX...", "tronque": false, "monday_post_id": 4820600759, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2026-01-15T08:59:48.000Z", "contenu": "le locataire contecte le fait de devoir paye le remplacement du chauffe eau\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbvMNlGvFdTrHNMCGvGNfhkbHmGhhPKgMwzcHpmgDqlcJmRWTGBnBsg...\n\n", "tronque": false, "monday_post_id": 4834042923, "parent_post_id": null}, {"monday_id": 10701522915, "auteur": "Marion Brenot", "le": "2026-01-15T09:03:43.000Z", "contenu": "Dispo de Luc de chez MBP pour intervenir 01 60 47 00 95\n\nlundi 16h 17h\n\n28 et 29 toute la journée ou